"use strict";(self.webpackChunkarchive_dernier_verre=self.webpackChunkarchive_dernier_verre||[]).push([[57617],{61560:(e,n,r)=>{r.r(n),r.d(n,{assets:()=>u,contentTitle:()=>o,default:()=>d,frontMatter:()=>a,metadata:()=>t,toc:()=>l});var t=r(26142),s=r(74848),i=r(28453);const a={title:"La cour des corbeaux",date:new Date("2022-02-22T00:00:00.000Z")},o=void 0,u={authorsImageUrls:[]},l=[{value:"La cour des corbeaux (2022)",id:"la-cour-des-corbeaux-2022",level:2},{value:"Origine",id:"origine",level:2},{value:"Les activit\xe9s",id:"les-activit\xe9s",level:2},{value:"La fin",id:"la-fin",level:2}];function c(e){const n={a:"a",code:"code",h2:"h2",p:"p",pre:"pre",strong:"strong",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.h2,{id:"la-cour-des-corbeaux-2022",children:"La cour des corbeaux (2022)"}),"\n",(0,s.jsx)(n.p,{children:"(soyez indulgent, c'\xe9tait le premier \xe9v\xe9nement du serveur et il n'y avait rien de clairement organis\xe9)"}),"\n",(0,s.jsx)("img",{src:"/ArchiveLeDernierVerre/img/Event/corbeau.png",id:"img_archive",alt:"Les corbeaux"}),"\n","\n",(0,s.jsx)(n.h2,{id:"origine",children:"Origine"}),"\n",(0,s.jsxs)(n.p,{children:["Le serveur \xe9tait encore tout jeune avec une trentaine de joueurs et, comme j'avais du temps \xe0 cette pr\xe9iode, j'ai d\xe9cid\xe9 de lanc\xe9 ce premier \xe9vent. Clairement, je n'avais ",(0,s.jsx)(n.strong,{children:"aucune"})," id\xe9e d'o\xf9 j'allais avec \xe7a. Je voulais simplement ajouter des \xe9v\xe9nements al\xe9atoire au RP libre qu'il faudrait prendre en compte et qui permettrait au passage d'\xe9liminer les personnages absents (\xe0 l'\xe9poque, il n'y avait pas de tri). La cour des corbeaux faisait \xe9cho \xe0 la cour des hiboux du lore de batman que je trouvais int\xe9ressant comme organisation \"l\xe9gale\" influant sur Langdorf."]}),"\n",(0,s.jsx)(n.p,{children:"Ainsi, le 19/02/2022, apparait cette annonce :"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-markdown",children:"`Nouvelles annonces :`\r\n\r\nLancement de l'event du serveur ! Pendant ces prochains jours, quelques r\xe8gles changent sur le serveur :\r\n\r\n- A tout moment, un incident ou un individu peuvent intervenir dans votre RP. Le message qui sera post\xe9 expliquera quels sont les impacts pour vos personnages. **Cette interruption est obligatoire \xe0 prendre en compte dans votre RP !** Si vous avez un emp\xeachement ou que vous mettez trop de temps \xe0 r\xe9pondre, l'orga a le droit - exceptionnellement - de jouer la r\xe9action de votre personnage si elle le juge n\xe9cessaire. De plus, la r\xe8gle interdisant la mort ou le handicap de personnage ne concerne pas l'event. Traduction : votre personnage pourra mourir ou \xeatre handicap\xe9 durant l'event, peu importe votre race. Tachez donc de jouer le fear RP car une tentative d'acte h\xe9ro\xefque risque de tr\xe8s mal finir.\r\n\r\n- Durant cette p\xe9riode, les organisateurs de l'event auront un rang d\xe9di\xe9. Leurs personnages peuvent continuer \xe0 RP mais sans pouvoir investiguer ni donner la moindre information sur l'event.\r\n\r\n- Il est possible que votre acc\xe8s \xe0 la zone RP du serveur soit modifi\xe9e. Je compte sur vous pour jouer le jeu et ne donner aucun d\xe9tail sur ce qu'il vous arrive durant cette p\xe9riode en HRP. C'est une occasion d'avoir beaucoup d'interaction en RP, ne la g\xe2chez pas.\r\n\r\n- Durant l'event, des informations pourront \xeatre donn\xe9es aux personnages qui investiguent autour de l'event. Ces informations seront transmises uniquement via message priv\xe9. Cependant, certains personnages peuvent avoir de fausses informations (ou tout simplement mentir). A vous de trouver s'il y a un ou plusieurs imposteurs et qui ment.\r\n\r\n- Il est bien entendu formellement interdit d'utiliser un tupper imitant les incidents et/ou individus. Seul l'organisation de l'event a le droit de l'utiliser\r\n\r\n**Si vous ne souhaitez pas participer \xe0 l'event :** Indiquez vous comme absent jusqu'\xe0 la fin de l'event. Vous aurez encore acc\xe8s \xe0 la zone HRP mais tout personnage qui RP sur cette p\xe9riode peut \xeatre interrompu par l'event\r\n\r\nJ'esp\xe8re que \xe7a vous plaira, que vous vous amuserez et soyez bienveillants & gentils avec l'orga de l'event qui fait tout \xe7a b\xe9n\xe9volement :redcat:\n"})}),"\n",(0,s.jsx)(n.h2,{id:"les-activit\xe9s",children:"Les activit\xe9s"}),"\n",(0,s.jsx)(n.p,{children:"Tout a commenc\xe9 par une enl\xe8vement \"accidentel\". Une recherche de RP leurre qui est devenue un enl\xe8vement. A l'\xe9poque, cela privait de l'acc\xe8s \xe0 tout le reste du serveur."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.a,{href:"/ArchiveLeDernierVerre/docs/Archives/Events/CourDesCorbeaux/2022-02-22_Alice_PNJ",children:"L'enl\xe8vement d'Alice"})," (22-02-2022)"]}),"\n",(0,s.jsx)(n.p,{children:"Puis il y eut l'enl\xe8vement de la vraie cible : Anastasia, la chef de la mafia russe, accompagn\xe9 de son assistant/amant, Ivan."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.a,{href:"/ArchiveLeDernierVerre/docs/Archives/Events/CourDesCorbeaux/2022-02-25_Anastasia_Ivan_PNJ",children:"L'enl\xe8vement d'Anastasia & Ivan"})," (25-02-2022)"]}),"\n",(0,s.jsx)(n.h2,{id:"la-fin",children:"La fin"}),"\n",(0,s.jsx)(n.p,{children:"le 25/02/2022, je publie cette annonce de cloture d'\xe9vent :"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-markdown",children:"`Nouvelles annonces :`\r\n\r\nApr\xe8s deux explosions, trois enl\xe8vements et de multiples incendies, **l'\xe9vent est termin\xe9**. Plus de dangers pour vos personnages, vous pouvez reprendre un RP normal. Evidemment, les cons\xe9quences sont \xe0 prendre en compte et il faudra reconstruire ce qui a \xe9t\xe9 d\xe9truit.\r\n\r\nPour ceux qui s'int\xe9resse \xe0 l'enqu\xeate : oui, il y aura d'autre \xe9v\xe9nements li\xe9s \xe0 celui ci. Oui, vous pouvez continuer les recherches et/ou demander des infos. Oui, il reste du lore \xe0 d\xe9couvrir.\r\n\r\nEn esp\xe9rant que \xe7a vous a plu, vous aussi :redcat:\n"})})]})}function d(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453:(e,n,r)=>{r.d(n,{R:()=>a,x:()=>o});var t=r(96540);const s={},i=t.createContext(s);function a(e){const n=t.useContext(i);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),t.createElement(i.Provider,{value:n},e.children)}},26142:e=>{e.exports=JSON.parse('{"permalink":"/ArchiveLeDernierVerre/blog/2022/220222_CourDesCorbeaux","source":"@site/blog/2022/220222_CourDesCorbeaux.mdx","title":"La cour des corbeaux","description":"La cour des corbeaux (2022)","date":"2022-02-22T00:00:00.000Z","tags":[],"readingTime":3.27,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"La cour des corbeaux","date":"2022-02-22T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"La r\xe9ception de fin d\'ann\xe9e","permalink":"/ArchiveLeDernierVerre/blog/2022/221229_ReceptionFinAnn\xe9e"}}')}}]);